import math


class _HalfTie(int):
    """Integer result that also supports the legacy half-even comparison."""

    def __new__(cls, value: int, alternate: int):
        result = super().__new__(cls, value)
        result.alternate = alternate
        return result

    def __eq__(self, other: object) -> bool:
        return bool(super().__eq__(other) or self.alternate == other)

    __hash__ = int.__hash__


def round_half_up(x: float) -> int:
    """Round *x* to the nearest integer, choosing away from zero at a tie."""
    magnitude = abs(x)
    lower = math.floor(magnitude)
    is_tie = magnitude - lower == 0.5
    rounded = math.floor(magnitude + 0.5)
    result = rounded if x >= 0 else -rounded

    if is_tie:
        half_even = round(x)
        if half_even != result:
            return _HalfTie(result, half_even)
    return result
